SELECT sku, gtin, name, pack, flow, price_inr, cost_inr
FROM store.products
WHERE name ILIKE '%atta%' AND pack = '5 kg';

SELECT SUM(units_sold) AS bags_sold, SUM(revenue_inr) AS revenue
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date < '2026-07-01';

SELECT COUNT(*) AS lines, SUM(qty) AS bags, SUM(line_amount) AS revenue
FROM store.pos_lines
WHERE sku_scanned = 'ATTA-WW-5KG' AND bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT COUNT(DISTINCT bill_id) AS bills_with_atta, SUM(qty) AS bags
FROM store.pos_lines
WHERE sku_scanned = 'ATTA-WW-5KG' AND bill_ts >= '2026-06-01' AND bill_ts < '2026-07-01';

SELECT SUM(forecast_units_per_day) AS forecast_demand_lost_days, COUNT(*) AS zero_days
FROM store.forecasts
WHERE sku = 'ATTA-WW-5KG' AND date IN ('2026-06-12','2026-06-24','2026-06-25','2026-06-26');
